const MAX_CONNECTIONS: u32 = 10_000;
static SERVER_NAME: &str = "TRAK_RUST_CORE";

fn main() {
    println!("=== 01: Basics, Immutability & Shadowing ===");

    // 1. Immutable by default
    let x = 5;
    println!("Immutable x = {x}");

    // 2. Mutable variable with 'mut'
    let mut y = 10;
    y += 5;
    println!("Mutable y = {y}");

    // 3. Variable Shadowing (can change type)
    let spaces = "   ";
    let spaces = spaces.len(); // Shadowed to usize!
    println!("Shadowed spaces count = {spaces}");

    println!("Constants: MAX_CONNECTIONS={MAX_CONNECTIONS}, SERVER={SERVER_NAME}");
}

fn main() {
    println!("=== 02: Data Types & Stack Memory Layout ===");

    // Primitives
    let integer: i32 = 42;
    let float: f64 = 3.14159;
    let boolean: bool = true;
    let character: char = '🦀'; // 4 bytes (Unicode Scalar)

    println!("Scalar Types: int={integer}, float={float}, bool={boolean}, char={character}");

    // Tuples
    let tuple: (i32, f64, u8) = (500, 6.4, 1);
    let (a, b, c) = tuple;
    println!("Tuple: a={a}, b={b}, c={c}, indexed={}", tuple.0);

    // Fixed-size Stack-allocated Array
    let arr: [i32; 5] = [1, 2, 3, 4, 5];
    println!("Array on stack: len={}, first={}", arr.len(), arr[0]);
}

fn main() {
    println!("=== 03: String vs &str and Fat Pointers ===");

    // String: Heap allocated, owned, growable
    let mut owned = String::from("Hello");
    owned.push_str(", Rust Systems!");

    // &str: String slice (Fat pointer: [ptr, len])
    let slice: &str = &owned[0..5];
    println!("Owned String: {owned}");
    println!("Borrowed Slice: {slice}");

    // Array slice (&[T])
    let nums = [10, 20, 30, 40, 50];
    let num_slice: &[i32] = &nums[1..4]; // [20, 30, 40]
    println!("Array slice: {:?}, len={}", num_slice, num_slice.len());
}

fn main() {
    println!("=== 04: Control Flow & Pattern Matching ===");

    // 1. if as an expression
    let is_fast = true;
    let speed = if is_fast { 100 } else { 20 };
    println!("Speed: {speed}");

    // 2. loop with break value
    let mut counter = 0;
    let result = loop {
        counter += 1;
        if counter == 5 {
            break counter * 10;
        }
    };
    println!("Loop result: {result}");

    // 3. Exhaustive match
    let number = 3;
    match number {
        1 => println!("One"),
        2 | 3 => println!("Two or Three"),
        4..=10 => println!("Between 4 and 10"),
        _ => println!("Something else"),
    }
}

fn main() {
    println!("=== 05: Functions & Closures (Fn, FnMut, FnOnce) ===");

    let factor = 2;
    // Closure capturing environment by reference
    let multiplier = |x: i32| x * factor;
    println!("Closure result: {}", multiplier(10));

    // Move closure: takes ownership of captured values
    let message = String::from("Rust");
    let consumer = move || println!("Consumed message: {message}");
    consumer();
}

fn longest<'a>(x: &'a str, y: &'a str) -> &'a str {
    if x.len() > y.len() { x } else { y }
}

fn main() {
    println!("=== 06: Ownership, Borrowing & Lifetimes ===");

    // 1. Move Semantics
    let s1 = String::from("hello");
    let s2 = s1; // s1 moved to s2! s1 is invalid now.
    println!("Owned s2: {s2}");

    // 2. Borrowing: Aliasing XOR Mutability
    let mut data = String::from("trak");
    {
        let r1 = &data; // Immutable borrow
        let r2 = &data; // Multiple immutable borrows OK
        println!("Borrows: {r1}, {r2}");
    }

    let r_mut = &mut data; // Exclusive mutable borrow
    r_mut.push_str("-engine");
    println!("Mutated data: {r_mut}");

    // 3. Lifetimes
    let str1 = "short";
    let str2 = "longer_string";
    println!("Longest: {}", longest(str1, str2));
}

enum Command {
    Quit,
    Move { x: i32, y: i32 },
    Write(String),
}

struct Player {
    name: String,
    health: u32,
}

impl Player {
    fn new(name: &str) -> Self {
        Self { name: name.to_string(), health: 100 }
    }

    fn take_damage(&mut self, dmg: u32) {
        self.health = self.health.saturating_sub(dmg);
    }
}

fn main() {
    println!("=== 07: Structs, Enums & Methods ===");
    let mut p = Player::new("Fighter");
    p.take_damage(30);
    println!("Player '{}' Health: {}", p.name, p.health);

    let cmd = Command::Move { x: 10, y: 20 };
    match cmd {
        Command::Quit => println!("Quit command"),
        Command::Move { x, y } => println!("Move to ({x}, {y})"),
        Command::Write(msg) => println!("Message: {msg}"),
    }
}

trait Summary {
    fn summarize(&self) -> String;
}

struct Article {
    headline: String,
}

impl Summary for Article {
    fn summarize(&self) -> String {
        format!("Article: {}", self.headline)
    }
}

// Static dispatch (monomorphization) with impl Trait
fn notify(item: &impl Summary) {
    println!("Notification: {}", item.summarize());
}

fn main() {
    println!("=== 08: Traits, Generics & Static vs Dynamic Dispatch ===");
    let a = Article { headline: String::from("Rust 2024 Edition Released!") };
    notify(&a);
}

use std::collections::HashMap;

fn main() {
    println!("=== 09: Collections & Functional Iterators ===");

    let mut map = HashMap::new();
    map.insert("key1", 100);
    println!("Map entry: {:?}", map.get("key1"));

    let nums = vec![1, 2, 3, 4, 5];
    let sum_of_even_squares: i32 = nums
        .iter()
        .filter(|&&x| x % 2 == 0)
        .map(|&x| x * x)
        .sum();

    println!("Sum of even squares: {sum_of_even_squares}");
}

fn divide(a: f64, b: f64) -> Result<f64, String> {
    if b == 0.0 {
        Err(String::from("Cannot divide by zero"))
    } else {
        Ok(a / b)
    }
}

fn calculate() -> Result<f64, String> {
    let val = divide(10.0, 2.0)?;
    Ok(val * 3.0)
}

fn main() {
    println!("=== 10: Error Handling with Option & Result ===");
    match calculate() {
        Ok(res) => println!("Calculation success: {res}"),
        Err(e) => println!("Error: {e}"),
    }
}

use std::rc::Rc;
use std::cell::RefCell;

fn main() {
    println!("=== 11: Smart Pointers (Box, Rc, RefCell) ===");

    // Box<T>: Heap allocation
    let b = Box::new(42);
    println!("Boxed value on heap: {b}");

    // Rc<RefCell<T>>: Shared reference with interior mutability
    let shared = Rc::new(RefCell::new(10));
    let clone1 = Rc::clone(&shared);
    *clone1.borrow_mut() += 5;

    println!("Shared mutable value: {}", shared.borrow());
}

